// generatedPath is the checked-in file this package produces.
var generatedPath = filepath.Join("..", "serverdef", "builtins_gen.go")

// TestGeneratedFileIsUpToDate is the test that makes a checked-in
// generated file trustworthy: the file in the tree is exactly what the
// generator produces from the vendored snapshot. A hand-edit of either
// side fails here.
func TestGeneratedFileIsUpToDate(t *testing.T) {
	want, err := Generate()
	if err != nil {
		t.Fatalf("Generate() = %v", err)
	}
	got, err := os.ReadFile(generatedPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Errorf("%s is stale or hand-edited; run `go generate ./internal/serverdef/`", generatedPath)
	}
}

// TestGenerateIsDeterministic: same snapshot, same bytes. Without this,
// the check above would fail at random and be disabled within a week.
func TestGenerateIsDeterministic(t *testing.T) {
	first, err := Generate()
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		again, err := Generate()
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(first, again) {
			t.Fatalf("run %d produced different bytes", i+2)
		}
	}
}

func TestGeneratedSourceShape(t *testing.T) {
	src, err := Generate()
	if err != nil {
		t.Fatal(err)
	}
	text := string(src)
	for _, want := range []string{
		"Code generated by internal/gen",
		"DO NOT EDIT",
		CorpusCommit,
		CorpusUpstream,
		CorpusLicense,
		"package serverdef",
		"var generatedProvenance = Provenance{",
		"var generatedBuiltins = []*ServerDef{",
	} {
		if !strings.Contains(text, want) {
			t.Errorf("generated source does not contain %q", want)
		}
	}
	// No timestamp, no absolute path, nothing machine-specific.
	for _, forbidden := range []string{os.Getenv("HOME"), "/tmp/", "20 Aug", "generated at"} {
		if forbidden == "" {
			continue
		}
		if strings.Contains(text, forbidden) {
			t.Errorf("generated source contains machine-specific text %q", forbidden)
		}
	}
}

// TestBuildAllExplainsItself: every definition records what came from
// the corpus, what was curated and what was left out. A generated table
// nobody can audit is a table nobody should trust.
func TestBuildAllExplainsItself(t *testing.T) {
	builtins, err := BuildAll()
	if err != nil {
		t.Fatalf("BuildAll() = %v", err)
	}
	if len(builtins) != len(curations) {
		t.Fatalf("got %d definitions, want %d", len(builtins), len(curations))
	}
	for _, b := range builtins {
		t.Run(b.Def.Name, func(t *testing.T) {
			if err := b.Def.Validate(); err != nil {
				t.Errorf("does not validate: %v", err)
			}
			if !slices.Contains(b.FromCorpus, "server.command") {
				t.Errorf("FromCorpus = %v, want the command to come from the corpus", b.FromCorpus)
			}
			if !slices.Contains(b.FromCorpus, "activation.languages") {
				t.Errorf("FromCorpus = %v, want the languages to come from the corpus", b.FromCorpus)
			}
			var curatedGlobs bool
			for _, n := range b.Curated {
				if n.Key == "activation.globs" {
					curatedGlobs = true
				}
				if n.Reason == "" {
					t.Errorf("curated key %q has no reason", n.Key)
				}
			}
			if !curatedGlobs {
				t.Error("globs are not recorded as curated, but the corpus has none")
			}
			for _, n := range b.NotImported {
				if n.Reason == "" {
					t.Errorf("not-imported key %q has no reason", n.Key)
				}
			}
		})
	}
}

// TestBuildAllMatchesTheShippedTable closes the loop: what the
// generator builds now is what the package actually serves.
func TestBuildAllMatchesTheShippedTable(t *testing.T) {
	builtins, err := BuildAll()
	if err != nil {
		t.Fatal(err)
	}
	shipped := serverdef.Builtins()
	if len(shipped) != len(builtins) {
		t.Fatalf("the package ships %d built-ins, the generator builds %d", len(shipped), len(builtins))
	}
	for i, b := range builtins {
		got, want := shipped[i], b.Def
		if got.Name != want.Name {
			t.Fatalf("built-in %d is %q, want %q (order must match too)", i, got.Name, want.Name)
		}
		if !slices.Equal(got.Server.Command, want.Server.Command) {
			t.Errorf("%s command = %v, want %v", got.Name, got.Server.Command, want.Server.Command)
		}
		if !slices.Equal(got.Activation.Languages, want.Activation.Languages) {
			t.Errorf("%s languages = %v, want %v", got.Name, got.Activation.Languages, want.Activation.Languages)
		}
		if !slices.Equal(got.Activation.RootMarkers, want.Activation.RootMarkers) {
			t.Errorf("%s root markers = %v, want %v", got.Name, got.Activation.RootMarkers, want.Activation.RootMarkers)
		}
		if !slices.Equal(got.Activation.Globs, want.Activation.Globs) {
			t.Errorf("%s globs = %v, want %v", got.Name, got.Activation.Globs, want.Activation.Globs)
		}
		if got.Install.Mise != want.Install.Mise {
			t.Errorf("%s install = %q, want %q", got.Name, got.Install.Mise, want.Install.Mise)
		}
	}
	if p := serverdef.BuiltinProvenance(); p.Commit != CorpusCommit || p.License != CorpusLicense {
		t.Errorf("shipped provenance = %+v, want the corpus constants", p)
	}
}

// TestLanguageIDMapping is the mapping that decides whether a server is
// ever selected, so it is checked directly rather than through the
// table.
func TestLanguageIDMapping(t *testing.T) {
	ids, dropped := languageIDs([]string{"c", "c.doxygen", "cpp", "cpp.doxygen", "objc", "objcpp", "cuda", "c"})
	want := []string{"c", "cpp", "objective-c", "objective-cpp", "cuda-cpp"}
	if !slices.Equal(ids, want) {
		t.Errorf("languageIDs() = %v, want %v", ids, want)
	}
	if !slices.Equal(dropped, []string{"c.doxygen", "cpp.doxygen"}) {
		t.Errorf("dropped = %v, want the Neovim compound filetypes", dropped)
	}
}

// TestCurationRequiresGlobs and its siblings check the generator's own
// guards: a curation that forgets something must fail generation, not
// ship a definition that never activates.
func TestCurationGuards(t *testing.T) {
	src, err := CorpusFile("gopls")
	if err != nil {
		t.Fatal(err)
	}
	cfg, err := ExtractCorpus("gopls", src)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := (curation{Name: "x", Corpus: "gopls", RootMarkers: []string{".git"}, RootMarkerReason: "test"}).build(cfg); err == nil {
		t.Error("a curation with no globs was accepted")
	}
	if _, err := (curation{Name: "x", Corpus: "gopls", Globs: []string{"**/*.go"}, RootMarkers: []string{".git"}}).build(cfg); err == nil {
		t.Error("curated root markers with no reason were accepted")
	}
	if _, err := (curation{Name: "x", Corpus: "gopls", Globs: []string{"**/*.go"}}).build(cfg); err == nil {
		t.Error("a definition with no root markers at all was accepted")
	}
}

func TestWriteAndResolveOutput(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "builtins_gen.go")
	if err := Write(path); err != nil {
		t.Fatalf("Write() = %v", err)
	}
	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	want, err := Generate()
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, want) {
		t.Error("Write() wrote something other than Generate()")
	}
	if entries, err := os.ReadDir(dir); err != nil {
		t.Fatal(err)
	} else if len(entries) != 1 {
		t.Errorf("Write() left %d files behind, want just the output", len(entries))
	}

	abs, err := ResolveOutput("")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.HasSuffix(abs, filepath.FromSlash(DefaultOutput)) {
		t.Errorf("ResolveOutput(\"\") = %q, want it to end in %q", abs, DefaultOutput)
	}
	if !filepath.IsAbs(abs) {
		t.Errorf("ResolveOutput() = %q, want an absolute path", abs)
	}
}

func TestWriteToUnwritablePath(t *testing.T) {
	if err := Write(filepath.Join(t.TempDir(), "no-such-dir", "out.go")); err == nil {
		t.Error("Write() to a missing directory succeeded")
	}
}

func TestEmitTableSortsKeys(t *testing.T) {
	var b strings.Builder
	emitTable(&b, "", map[string]any{
		"z": true,
		"a": "s",
		"m": map[string]any{"y": int64(2), "b": 1.5, "n": nil},
	})
	got := b.String()
	if strings.Index(got, `"a"`) > strings.Index(got, `"m"`) || strings.Index(got, `"m"`) > strings.Index(got, `"z"`) {
		t.Errorf("keys are not sorted:\n%s", got)
	}
	for _, want := range []string{`"a": "s"`, `"b": 1.5`, `"y": 2`, `"n": nil`, `"z": true`} {
		if !strings.Contains(got, want) {
			t.Errorf("output does not contain %q:\n%s", want, got)
		}
	}
}

func TestWrap(t *testing.T) {
	if got := wrap("", 10); got != nil {
		t.Errorf("wrap(\"\") = %v, want nil", got)
	}
	lines := wrap("one two three four five six seven", 10)
	for _, line := range lines {
		if len(line) > 10 && !strings.Contains(line, " ") {
			t.Errorf("line %q is longer than the width and unbreakable", line)
		}
	}
	if strings.Join(lines, " ") != "one two three four five six seven" {
		t.Errorf("wrap() lost or reordered words: %v", lines)
	}
}
